/**
 * Tests {@link ServicesForMetadata#createCompoundCRS ReferencingUtilities.createCompoundCRS(…)}.
 *
 * @throws FactoryException if a CRS can not be created.
 *
 * @see <a href="https://issues.apache.org/jira/browse/SIS-303">SIS-303</a>
 *
 * @since 0.7
 */
@Test
public void testCreateCompoundCRS() throws FactoryException {
    final ReferencingServices services = ServicesForMetadata.getInstance();
    final GeodeticObjectFactory factory = new GeodeticObjectFactory();
    final Map<String, String> properties = Collections.singletonMap(CoordinateReferenceSystem.NAME_KEY, "WGS 84 (4D)");
    /*
         * createCompoundCRS(…) should not combine GeographicCRS with non-ellipsoidal height.
         */
    CoordinateReferenceSystem compound = services.createCompoundCRS(factory, factory, properties, HardCodedCRS.WGS84, HardCodedCRS.GRAVITY_RELATED_HEIGHT, HardCodedCRS.TIME);
    assertArrayEqualsIgnoreMetadata(new SingleCRS[] { HardCodedCRS.WGS84, HardCodedCRS.GRAVITY_RELATED_HEIGHT, HardCodedCRS.TIME }, CRS.getSingleComponents(compound).toArray());
    /*
         * createCompoundCRS(…) should combine GeographicCRS with ellipsoidal height.
         */
    compound = services.createCompoundCRS(factory, factory, properties, HardCodedCRS.WGS84, HardCodedCRS.ELLIPSOIDAL_HEIGHT);
    assertArrayEqualsIgnoreMetadata(new SingleCRS[] { HardCodedCRS.WGS84_3D }, CRS.getSingleComponents(compound).toArray());
    /*
         * createCompoundCRS(…) should combine GeographicCRS with ellipsoidal height and keep time.
         */
    compound = services.createCompoundCRS(factory, factory, properties, HardCodedCRS.WGS84, HardCodedCRS.ELLIPSOIDAL_HEIGHT, HardCodedCRS.TIME);
    assertArrayEqualsIgnoreMetadata(new SingleCRS[] { HardCodedCRS.WGS84_3D, HardCodedCRS.TIME }, CRS.getSingleComponents(compound).toArray());
    /*
         * Non-standard feature: accept (VerticalCRS + GeodeticCRS) order.
         * The test below use the reverse order for all axes compared to the previous test.
         */
    compound = services.createCompoundCRS(factory, factory, properties, HardCodedCRS.TIME, HardCodedCRS.ELLIPSOIDAL_HEIGHT, HardCodedCRS.WGS84_φλ);
    final Object[] components = CRS.getSingleComponents(compound).toArray();
    assertEquals(2, components.length);
    assertEqualsIgnoreMetadata(HardCodedCRS.TIME, components[0]);
    assertInstanceOf("Shall be a three-dimensional geographic CRS.", GeographicCRS.class, components[1]);
    assertAxisDirectionsEqual("Shall be a three-dimensional geographic CRS.", ((CoordinateReferenceSystem) components[1]).getCoordinateSystem(), AxisDirection.UP, AxisDirection.NORTH, AxisDirection.EAST);
}

