@Test
public void testSort() {
    assertOrdered(new CoordinateSystemAxis[] { HardCodedAxes.GEODETIC_LONGITUDE, HardCodedAxes.GEODETIC_LATITUDE, HardCodedAxes.ELLIPSOIDAL_HEIGHT }, new CoordinateSystemAxis[] { HardCodedAxes.GEODETIC_LONGITUDE, HardCodedAxes.GEODETIC_LATITUDE, HardCodedAxes.ELLIPSOIDAL_HEIGHT });
    assertOrdered(new CoordinateSystemAxis[] { HardCodedAxes.GEODETIC_LONGITUDE, HardCodedAxes.GEODETIC_LATITUDE, HardCodedAxes.ELLIPSOIDAL_HEIGHT }, new CoordinateSystemAxis[] { HardCodedAxes.GEODETIC_LATITUDE, HardCodedAxes.ELLIPSOIDAL_HEIGHT, HardCodedAxes.GEODETIC_LONGITUDE });
    // A plausible CS.
    assertOrdered(new AxisDirection[] { // Right handed-rule
    AxisDirection.EAST, // Right handed-rule
    AxisDirection.NORTH, AxisDirection.UP }, new AxisDirection[] { AxisDirection.NORTH, AxisDirection.UP, AxisDirection.EAST });
    // A very dummy CS just for testing. The order of
    // any non-compass direction should be unchanged.
    assertOrdered(new AxisDirection[] { // Right handed-rule
    AxisDirection.NORTH_EAST, // Right handed-rule
    AxisDirection.NORTH_NORTH_WEST, AxisDirection.GEOCENTRIC_X, AxisDirection.GEOCENTRIC_Y, AxisDirection.PAST }, new AxisDirection[] { AxisDirection.GEOCENTRIC_Y, AxisDirection.NORTH_NORTH_WEST, AxisDirection.GEOCENTRIC_X, AxisDirection.NORTH_EAST, AxisDirection.PAST });
    // An other plausible CS.
    assertOrdered(new AxisDirection[] { // Right handed-rule
    AxisDirection.WEST, // Right handed-rule
    AxisDirection.SOUTH, AxisDirection.DOWN }, new AxisDirection[] { AxisDirection.SOUTH, AxisDirection.DOWN, AxisDirection.WEST });
    // An other plausible CS.
    assertOrdered(new AxisDirection[] { // Right handed-rule
    AxisDirection.SOUTH, // Right handed-rule
    AxisDirection.EAST, AxisDirection.DOWN }, new AxisDirection[] { AxisDirection.SOUTH, AxisDirection.DOWN, AxisDirection.EAST });
    // Legacy (WKT 1) geocentric axes.
    assertOrdered(new AxisDirection[] { AxisDirection.OTHER, AxisDirection.EAST, AxisDirection.NORTH }, new AxisDirection[] { AxisDirection.NORTH, AxisDirection.OTHER, AxisDirection.EAST });
}

