    matrix = Matrices.create(5, 5, new double[] { 20, 0, 0, 0, -3000, 0, -20, 0, 0, 4000, 0, 0, 0, 2, NaN, 0, 0, 400, 0, 2000, 0, 0, 0, 0, 1 });
